      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LB_1RC0RB_1LD1RA_0RB0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LB_1RC0RB_1LD1RA_0RB0LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3]).
