  unfold Cc_1RB0LC_0LC0RB_0LD1LC_1RA0LA, cden, Z0_1RB0LC_0LC0RB_0LD1LC_1RA0LA, Z1_1RB0LC_0LC0RB_0LD1LC_1RA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LC_0LC0RB_0LD1LC_1RA0LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j P0_1RB0LC_0LC0RB_0LD1LC_1RA0LA /\
  cden (Dp q0 ++ [S0]) [] j P1_1RB0LC_0LC0RB_0LD1LC_1RA0LA = Cc (Pos.succ p).
Proof.
