Lemma lapi_1RB0LC_0LC0RB_0LD1LC_1RA0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
