               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LC_0LC0RB_0LD1LC_1RA0LA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LC_0LC0RB_0LD1LC_1RA0LA P0_1RB0LC_0LC0RB_0LD1LC_1RA0LA P1_1RB0LC_0LC0RB_0LD1LC_1RA0LA 4 8
