Lemma geo_1RB0LC_0LC0RB_0LD1LC_1RA0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_0LC0RB_0LD1LC_1RA0LA) = lift (Cc (Pos.succ p)).
