(** ** The lap *)

Lemma lap_1RB0LC_0LC0RB_0LD1LC_1RA0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
