  - destruct (lapi_1RB0LC_0LC0RB_0LD1LC_1RA0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_0LC0RB_0LD1LC_1RA0LA B0_1RB0LC_0LC0RB_0LD1LC_1RA0LA B1_1RB0LC_0LC0RB_0LD1LC_1RA0LA 4 8 p j' [] []).
    + exact run_ovf_1RB0LC_0LC0RB_0LD1LC_1RA0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_0LC0RB_0LD1LC_1RA0LA p j' E).
    + exact (geo_1RB0LC_0LC0RB_0LD1LC_1RA0LA p j' E).
    + lia.
Qed.

