(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_1LA1RA_0LB1LD_0RB1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] 0 Z0_1RB0LC_1LA1RA_0LB1LD_0RB1LD /\
  cden (Jp q0 ++ [S0;S1;S0]) [] 0 Z1_1RB0LC_1LA1RA_0LB1LD_0RB1LD = Cc (Pos.succ p).
Proof.
