    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LC_1LA1RA_0LB1LD_0RB1LD Z0_1RB0LC_1LA1RA_0LB1LD_0RB1LD Z1_1RB0LC_1LA1RA_0LB1LD_0RB1LD 0 4
               run_z_1RB0LC_1LA1RA_0LB1LD_0RB1LD (Jp q0 ++ [S0;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LC_1LA1RA_0LB1LD_0RB1LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LC_1LA1RA_0LB1LD_0RB1LD P0_1RB0LC_1LA1RA_0LB1LD_0RB1LD P1_1RB0LC_1LA1RA_0LB1LD_0RB1LD 4 8
