    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LC_1LA1RA_0LB1LD_0RB1LD B0_1RB0LC_1LA1RA_0LB1LD_0RB1LD B1_1RB0LC_1LA1RA_0LB1LD_0RB1LD 4 10 p j' [] []).
    + exact run_ovf_1RB0LC_1LA1RA_0LB1LD_0RB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LC_1LA1RA_0LB1LD_0RB1LD p j' E).
    + exact (geo_1RB0LC_1LA1RA_0LB1LD_0RB1LD p j' E).
