Definition cho_1RB0LC_1LA1RA_1LD1LD_0RB1LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 5; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_ovf_1RB0LC_1LA1RA_1LD1LD_0RB1LD : srun tm true true cho_1RB0LC_1LA1RA_1LD1LD_0RB1LD B0_1RB0LC_1LA1RA_1LD1LD_0RB1LD = Some (B1_1RB0LC_1LA1RA_1LD1LD_0RB1LD, 4, 10).
